import { AgentCoreApplication, type AgentCoreApplicationProps } from '@aws/agentcore-cdk';
import { Stack, type StackProps } from 'aws-cdk-lib';
import * as iam from 'aws-cdk-lib/aws-iam';
import { Construct } from 'constructs';

/** One target of agentcore/runtime-env.json, generated by `mise run ac-gen` from the config. */
export interface RuntimeEnv {
  /** Env vars of every runtime that differ by environment, such as ENV_NAME and CONFIG_SSM_PARAM_NAME. */
  envVars: Record<string, string>;
  /** The SSM parameter that holds the config; every runtime may read it. */
  configSsmParamArn: string;
}

export interface AgentCoreStackProps extends StackProps {
  /** Props for the AgentCore application, produced by transformAgentCoreJson from agentcore/agentcore.json. */
  application: AgentCoreApplicationProps;
  /** The target's entry of agentcore/runtime-env.json; absent for the target-less `agentcore build` stack. */
  runtimeEnv?: RuntimeEnv;
}

/**
 * The stack the AgentCore CLI deploys. Everything declared in agentcore/agentcore.json is
 * created by the AgentCoreApplication construct. Add your own resources below it and wire
 * them to your runtimes and harnesses through the application's accessors.
 */
export class AgentCoreStack extends Stack {
  public readonly application: AgentCoreApplication;

  constructor(scope: Construct, id: string, props: AgentCoreStackProps) {
    super(scope, id, props);
    this.application = new AgentCoreApplication(this, 'Application', props.application);

    // The agent calls the MCP server with SigV4 (AWS_IAM): bind() grants the agent's role
    // bedrock-agentcore:InvokeAgentRuntime on the MCP runtime and sets the agent's env var
    // AGENTCORE_RUNTIME_POWERPLANTMCP_ARN to its ARN. The runtime names come from
    // agentcore.json, generated from the config (agentcore_runtime_name_* in config_01_name.py).
    this.application.runtime('PowerPlantMcp').bind(this.application.runtime('SiteAgent'));

    // Every runtime reads its config from SSM (Config.load in config_00_main.py): it gets the
    // target's env vars and may read the parameter. A SecureString with the AWS-managed key
    // aws/ssm needs no kms grant: that key's policy allows its use through SSM in the account.
    if (props.runtimeEnv) {
      for (const runtime of this.application.runtimes.values()) {
        for (const [name, value] of Object.entries(props.runtimeEnv.envVars)) {
          runtime.addEnvironmentVariable(name, value);
        }
        iam.Grant.addToPrincipal({
          grantee: runtime,
          actions: ['ssm:GetParameter'],
          resourceArns: [props.runtimeEnv.configSsmParamArn],
        });
      }
    }

    // Example: give a runtime a DynamoDB table.
    //
    // import * as dynamodb from 'aws-cdk-lib/aws-dynamodb';
    // const orders = new dynamodb.Table(this, 'Orders', {
    //   partitionKey: { name: 'pk', type: dynamodb.AttributeType.STRING },
    // });
    // const checkout = this.application.runtime('checkout'); // or .harness('support')
    // checkout.grantReadWrite(orders);
    // checkout.addEnvironmentVariable('ORDERS_TABLE', orders.tableName);
  }
}
